      /* 1. Sightings that began with a loss run the oldest alarm. */
      if (a.status === 'loss') return 'sudden_loss';
      /* 2. A decision surfacing through signs is the two-future freeze. */
      if (pattern === 'decision-surfacing' || a.want === 'decision-sign') return 'choice_friction';
      /* 3. A reassurance loop is the watchdog that won't stand down. */
      if (pattern === 'reassurance-loop') return 'scarcity_panic';
      /* 4. Passive waiting is the energy-saving strike. */
      if (pattern === 'passive-waiting' || a.want === 'coming') return 'stagnation_void';
      /* 5. Person-linked sightings and message-certainty are the pattern-making machine. */
      if (a.want === 'person' || a.attribution === 'message' || a.want === 'beneath') return 'illusion_fixation';
      /* 6. Too little data + a question this big = projection in a vacuum. */
      if (pattern === 'not-enough-evidence') return 'illusion_fixation';
      /* 7. Default: attachment-era hypervigilance. */
      return 'scarcity_panic';
