    resolve: function (answers) {
      var S = {
        acknowledgment: { 'honestly-ended': 2, 'ending-in-motion': 1, unclear: 0, 'form-maintained': -1, denied: -2, notell: null },
        completion:     { completed: 2, working: 1, mixed: 0, 'closure-waiting': -1, skipping: -2, notell: null },
        release:        { integrated: 2, sorting: 1, untouched: 0, carrying: -1, repeating: -2, notell: null },
        gravity:        { settling: 2, 'sad-clear': 1, neutral: 0, anxious: -1, dread: -2, notell: null }
      };
      var keys = ['acknowledgment', 'completion', 'release', 'gravity'];
      var sum = 0, uncertain = 0, vals = {};
      for (var i = 0; i < keys.length; i++) {
        var v = S[keys[i]][answers[keys[i]]];
        if (v === null || typeof v === 'undefined') { uncertain++; vals[keys[i]] = null; continue; }
        sum += v; vals[keys[i]] = v;
      }
      if (uncertain >= 2 && Math.abs(sum) < 3) return 'not-enough-evidence';
      if (vals.completion !== null && vals.completion <= -2) return 'premature-release';
      if (vals.release !== null && vals.release <= -2) return 'unacknowledged-ending';
      if (vals.acknowledgment !== null && vals.acknowledgment <= -1) return 'unacknowledged-ending';
      if (sum >= 4) return 'honest-completion';
      if (sum >= 1) return 'ending-in-progress';
      if (sum <= -2) return 'unacknowledged-ending';
      return 'not-enough-evidence';
    },

