      var w = answers.want, h = answers.help;
      if (h === 'unsure') return 'general';
      if (w === 'loss') return 'closure';
      if (w === 'meaning' || h === 'interpret') return 'free_first';
      if (w === 'ending' || h === 'dynamic') return 'tarot_relationship';
      if (w === 'complete' || h === 'deeper') return 'tarot_deep';
      if (w === 'next' || h === 'guidance') return 'tarot_decision';
      if (h === 'insight') return 'psychic';
      if (w === 'beneath') return 'tarot_deep';
      return 'general';
