    matchAha: function (a, pattern) {
      /* 1. Sightings inside grief or a breakup run the oldest alarm. */
      if (a.status === 'grief' || a.status === 'breakup' || a.want === 'loss') return 'sudden_loss';
      /* 2. An unadmitted ending is the two-future freeze — keeping both
         futures alive by not making the call. */
      if (pattern === 'unacknowledged-ending' || a.acknowledgment === 'denied' || a.acknowledgment === 'form-maintained') return 'choice_friction';
      /* 3. Rushing past completion is the pattern-making machine writing
         the next story. */
      if (pattern === 'premature-release' || a.want === 'next' || a.want === 'beneath') return 'illusion_fixation';
      /* 4. Dread around the sightings is the watchdog that won't stand down. */
      if (a.gravity === 'dread' || a.gravity === 'anxious') return 'scarcity_panic';
      /* 5. Maintaining a dead form is the energy-saving strike. */
      if (a.status === 'stuck') return 'stagnation_void';
      /* 6. Too little data + a question this big = projection in a vacuum. */
      if (pattern === 'not-enough-evidence') return 'illusion_fixation';
      /* 7. Default: uncertainty hypervigilance. */
      return 'scarcity_panic';
    },

