    resolve: function (answers) {
      var S = {
        use:       { lens: 2, conversation: 1, unused: 0, label: -1, verdict: -2, notell: null },
        resonance: { 'specific-fit': 2, mostly: 1, 'mixed-res': 0, flattered: -1, forced: -2, notell: null },
        authority: { none: 2, nudge: 1, untested: 0, input: -1, driver: -2, notell: null },
        pattern:   { named: 2, roughly: 1, looking: 0, abstract: -1, adopted: -2, notell: null }
      };
      var keys = ['use', 'resonance', 'authority', 'pattern'];
      var sum = 0, uncertain = 0, vals = {};
      for (var i = 0; i < keys.length; i++) {
        var v = S[keys[i]][answers[keys[i]]];
        if (v === null || typeof v === 'undefined') { uncertain++; vals[keys[i]] = null; continue; }
        sum += v; vals[keys[i]] = v;
      }
      if (uncertain >= 2 && Math.abs(sum) < 3) return 'not-enough-evidence';
      if (vals.resonance !== null && vals.resonance <= -2) return 'barnum-capture';
      if (answers.status === 'master-number' && vals.resonance !== null && vals.resonance <= -1) return 'barnum-capture';
      if (vals.authority !== null && vals.authority <= -2) return 'identity-anchor';
      if (vals.use !== null && vals.use <= -2) return 'identity-anchor';
      if (sum >= 4) return 'working-lens';
      if (sum >= 1) return 'pattern-surfacing';
      if (sum <= -2) return 'identity-anchor';
      return 'not-enough-evidence';
    },

