    matchAha: function (a, pattern) {
      /* 1. A crossroads lookup is the two-future freeze. */
      if (a.trigger === 'crossroads') return 'choice_friction';
      /* 2. Flattery capture is the pattern-making machine. */
      if (pattern === 'barnum-capture' || a.want === 'master') return 'illusion_fixation';
      /* 3. An identity anchor or an identity-driven lookup is the
         submission-signal family — outsourcing the self to a verdict. */
      if (pattern === 'identity-anchor' || a.trigger === 'identity') return 'identity_crisis';
      /* 4. Non-resonance with a stuck feeling is the energy-saving strike. */
      if (a.status === 'doesnt-fit' && a.want === 'fit') return 'stagnation_void';
      /* 5. Too little data + a question this big = projection in a vacuum. */
      if (pattern === 'not-enough-evidence') return 'illusion_fixation';
      /* 6. Default: certainty-hoarding about the self. */
      return 'scarcity_panic';
    },

