    resolve: function (answers) {
      var S = {
        balance:        { 'both-present': 2, 'mostly-me': 1, 'unclear-bal': 0, 'mostly-other': -1, 'one-missing': -2, notell: null },
        responsibility: { chosen: 2, accepted: 1, 'mixed-resp': 0, inherited: -1, borrowed: -2, notell: null },
        tempo:          { angled: 2, patient: 1, drifting: 0, pushing: -1, forcing: -2, notell: null },
        framing:        { prompt: 2, mirror: 1, 'undecided-fr': 0, reassurance: -1, confirmation: -2, notell: null }
      };
      var keys = ['balance', 'responsibility', 'tempo', 'framing'];
      var sum = 0, uncertain = 0, vals = {};
      for (var i = 0; i < keys.length; i++) {
        var v = S[keys[i]][answers[keys[i]]];
        if (v === null || typeof v === 'undefined') { uncertain++; vals[keys[i]] = null; continue; }
        sum += v; vals[keys[i]] = v;
      }
      if (uncertain >= 2 && Math.abs(sum) < 3) return 'not-enough-evidence';
      if (vals.responsibility !== null && vals.responsibility <= -2) return 'borrowed-responsibility';
      if (vals.balance !== null && vals.balance <= -2) return 'one-sided-balance';
      if (vals.tempo !== null && vals.tempo <= -2) return 'pause-for-angle';
      if (vals.responsibility !== null && vals.responsibility <= -1 && (vals.balance === null || vals.balance <= 0)) return 'borrowed-responsibility';
      if (vals.balance !== null && vals.balance <= -1 && (vals.tempo === null || vals.tempo <= 0)) return 'one-sided-balance';
      if (sum >= 3) return 'honest-dialogue';
      return 'pause-for-angle';
    },

