    resolve: function (answers) {
      var S = {
        presence: { present: 2, 'mostly-present': 1, 'unclear-pres': 0, restless: -1, intolerable: -2, notell: null },
        filling:  { 'letting-form': 2, exploring: 1, drifting: 0, auditioning: -1, grabbed: -2, notell: null },
        timing:   { 'active-timing': 2, 'patient-timing': 1, 'undecided-timing': 0, waiting: -1, owed: -2, notell: null },
        framing:  { 'space-marker': 2, mirror: 1, 'undecided-fr': 0, reassurance: -1, confirmation: -2, notell: null }
      };
      var keys = ['presence', 'filling', 'timing', 'framing'];
      var sum = 0, uncertain = 0, vals = {};
      for (var i = 0; i < keys.length; i++) {
        var v = S[keys[i]][answers[keys[i]]];
        if (v === null || typeof v === 'undefined') { uncertain++; vals[keys[i]] = null; continue; }
        sum += v; vals[keys[i]] = v;
      }
      if (uncertain >= 2 && Math.abs(sum) < 3) return 'not-enough-evidence';
      if (vals.filling !== null && vals.filling <= -2) return 'premature-filling';
      if (vals.timing !== null && vals.timing <= -2) return 'passive-waiting';
      if (vals.filling !== null && vals.filling <= -1 && (vals.presence === null || vals.presence <= 0)) return 'premature-filling';
      if (vals.timing !== null && vals.timing <= -1 && (vals.filling === null || vals.filling <= 0)) return 'passive-waiting';
      if (sum >= 3 && (answers.status === 'before-beginning' || answers.want === 'next')) return 'threshold-with-pull';
      if (sum >= 0) return 'present-in-the-space';
      return 'passive-waiting';
    },

