    resolve: function (answers) {
      var a = answers;
      var S = {
        depth:         { daily: 2, often: 1, 'sun-only': -1, notell: null },
        use:           { 'self-view': 2, language: 1, nothing: -1, notell: null },
        agency:        { build: 2, mix: 1, written: -2, notell: null },
        contradiction: { recalibrate: 2, 'weigh-it': 1, abandon: -2, notell: null }
      };
      var keys = ['depth', 'use', 'agency', 'contradiction'];
      var sum = 0, uncertain = 0, vals = {};
      for (var i = 0; i < keys.length; i++) {
        var v = S[keys[i]][a[keys[i]]];
        if (v === null || typeof v === 'undefined') { uncertain++; vals[keys[i]] = null; continue; }
        sum += v; vals[keys[i]] = v;
      }
      /* The certified-fate use is the misuse worth catching first. */
      if (a.trigger === 'fate-check' || a.agency === 'written') return 'destiny-verdict';
      /* The permission-slip use. */
      if (a.contradiction === 'abandon' || a.trigger === 'crossroads') return 'escape-permission';
      /* Genuine self-inquiry. */
      if (a.trigger === 'self-knowledge') return 'self-inquiry';
      if (uncertain >= 2 && Math.abs(sum) < 3) return 'not-enough-evidence';
      if (sum >= 1) return 'self-inquiry';
      return (sum <= -1) ? 'skeptical-explorer' : 'self-inquiry';
    },

