    resolve: function (answers) {
      var S = {
        tell:    { life: 2, both: 2, body: 1, express: 1, global: 0, unsure: null },
        reframe: { reflective: 2, both: 2, open: 1, literal: -2, health: -2, unsure: null },
        bypass:  { direct: 2, mostly: 1, mixed: 0, defer: -1, avoid: -2, unsure: null },
        range:   { flex: 2, some: 0, swing: 0, closed: -1, notyet: null, unsure: null }
      };
      var keys = ['tell', 'reframe', 'bypass', 'range'];
      var sum = 0, uncertain = 0, vals = {};
      for (var i = 0; i < keys.length; i++) {
        var v = S[keys[i]][answers[keys[i]]];
        if (v === null || typeof v === 'undefined') { uncertain++; vals[keys[i]] = null; continue; }
        sum += v; vals[keys[i]] = v;
      }
      if (vals.reframe === -2) return 'blockage-diagnosis';
      if (vals.bypass === -2) return 'clearance-bypass';
      if (uncertain >= 2 && Math.abs(sum) < 3) return 'not-enough-evidence';
      if (sum >= 4 && (answers.tell === 'life' || answers.tell === 'both' || answers.tell === 'express')) return 'located-friction';
      if (sum >= 4) return 'unlocated-friction';
      return 'not-enough-evidence';
    },

